<?php
require_once __DIR__.'/requirement_document_common.php';rdUser();
try{$id=trim((string)($_GET['id']??''));$doc=rdDocument($pdo,$id);$doc['metadata']=json_decode($doc['metadata']??'{}',true)?:[];
$q=$pdo->prepare('SELECT id,editor_block_id,block_type,content FROM requirement_document_blocks WHERE document_id=? ORDER BY sort_order,id');$q->execute([$id]);$blocks=[];foreach($q->fetchAll(PDO::FETCH_ASSOC)as$r){$data=json_decode($r['content'],true)?:[];$data['_recordId']=$r['id'];$b=['type'=>$r['block_type'],'data'=>$data];if($r['editor_block_id'])$b['id']=$r['editor_block_id'];$blocks[]=$b;}
$rel=$pdo->prepare("SELECT l.id,CASE WHEN l.target_document_id=? THEN 'parent' ELSE 'child' END role,o.id related_id,o.requirement_key,o.requirement_type,o.title,o.status,l.description FROM requirement_document_links l JOIN requirement_documents o ON o.id=CASE WHEN l.target_document_id=? THEN l.source_document_id ELSE l.target_document_id END WHERE l.link_type='parent_of' AND (l.source_document_id=? OR l.target_document_id=?) ORDER BY role,o.requirement_key");$rel->execute([$id,$id,$id,$id]);$parents=[];$children=[];foreach($rel->fetchAll(PDO::FETCH_ASSOC)as$r){if($r['role']==='parent')$parents[]=$r;else$children[]=$r;}
$ent=$pdo->prepare('SELECT id,entity_type,entity_id,relation_type,label,metadata FROM requirement_document_entity_links WHERE document_id=? ORDER BY entity_type,label');$ent->execute([$id]);$entities=$ent->fetchAll(PDO::FETCH_ASSOC);foreach($entities as&$r)$r['metadata']=json_decode($r['metadata']??'{}',true)?:[];
rdResponse(['success'=>true,'document'=>$doc,'editor'=>['time'=>(int)(microtime(true)*1000),'blocks'=>$blocks,'version'=>'2.31.0'],'relations'=>['parents'=>$parents,'children'=>$children],'entity_links'=>$entities]);}catch(Throwable$e){rdResponse(['success'=>false,'error'=>$e->getMessage()],500);}
